blocks.text:
.page {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-areas:
    "head head"
    "side main"
    "foot foot";
}
.header { grid-area: head; }
.sidebar { grid-area: side; }
.main { grid-area: main; }

/* 이기려고 선택자를 길게 쓰는 대신, 층을 나눈다 */
@layer base, components, utilities;

@layer base       { p { color: #333 } }
@layer utilities  { .muted { color: #888 } }   /* 층이 늦으면 이긴다. 구체성과 무관 */

:root {
  --accent: #a79bef;
  --gap: 1rem;
  --radius: 10px;
}
.btn { background: var(--accent); padding: var(--gap); border-radius: var(--radius); }

/* 어두운 화면에서 이름은 그대로, 값만 갈아 끼운다 */
@media (prefers-color-scheme: dark) {
  :root { --accent: #6f5fd6; }
}

/* 기본 = 좁은 화면 */
.page { display: grid; gap: 1rem; }

/* 넓어지면 더한다. 빼는 게 아니라 */
@media (min-width: 48rem) {
  .page { grid-template-columns: 240px 1fr; }
}
